    import random
    import time

    LANGUAGE_WRAPPER = 'Let A1A2...A_n be a regular n-gon. On the side A1A2, construct externally a regular {m}-gon that shares A1A2 as one of its sides; let B be the vertex of this {m}-gon adjacent to A1 (so triangle A1A2B lies outside the original n-gon). Determine the largest integer n for which A1, A_n, and B are consecutive vertices of some regular polygon.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Pick m in a broad range to produce diverse, nontrivial instances.
# Avoid m < 3 and ensure external construction is meaningful.
m = rng.randint(3, 60)
return {'m': m}

    def verifier(assign):
# We re-derive the formula rigorously.
# Let alpha_n = interior angle at a vertex of the n-gon, alpha_n = pi - 2*pi/n.
# Let alpha_m = interior angle at a vertex of the external m-gon, alpha_m = pi - 2*pi/m.
# With the given orientation (external), the smaller angle between A1A_n and A1B equals 2*pi/m + 2*pi/n.
# For A1, A_n, B to be consecutive vertices of some regular t-gon, that angle must equal alpha_t = pi - 2*pi/t.
# Hence: pi - 2*pi/t = 2*pi/m + 2*pi/n -> 1/t = 1/2 - 1/m - 1/n.
# Solving for n given m, t integer >= 3 and positivity constraints yields:
# 1/n = (m-2)/(2m) - 1/t.
# To maximize n, choose t as the smallest integer strictly greater than 2m/(m-2).
# This ensures 1/n > 0 and is minimal (thus n maximal).
# The resulting n is n = (2*m*t) / (t*(m-2) - 2*m), which turns out to be an integer for the minimal t.

# Validate input
if 'm' not in assign:
    # missing slot
    return (False, None)
m = assign['m']
if not isinstance(m, int):
    # wrong type
    return (False, None)
if m < 3:
    # degenerate external polygon
    return (False, None)

# Compute t_min = floor(2m/(m-2)) + 1 without floating errors
# Note: m-2 > 0 for m >= 3
num = 2 * m
den = m - 2
# floor division
q = num // den
t_min = q + 1
if t_min < 3:
    # minimal t must be at least 3
    t_min = 3

# Compute n using integer arithmetic
denom = t_min * (m - 2) - 2 * m
if denom <= 0:
    # Shouldn't happen if t_min is chosen as above; guard anyway
    return (False, None)
n = (2 * m * t_min) // denom

# Enforce that it divides exactly (to ensure n is integer as required)
if (2 * m * t_min) % denom != 0:
    # If non-integer, instance is invalid (this shouldn't occur for t_min choice, but we guard)
    return (False, None)

# Additional geometric sanity check: resulting angle must be < pi
# Equivalent to 2*pi/m + 2*pi/n < pi -> 1/n < 1/2 - 1/m
# Check via rationals without pi
lhs_num = 1
lhs_den = n
rhs_num = m - 2
rhs_den = 2 * m
# Compare 1/n < (m-2)/(2m) -> cross-multiply: 2m < n*(m-2)
if 2 * m >= n * (m - 2):
    return (False, None)

# All checks passed; return the answer
return (True, n)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

